"""The 100 databases: what each PDF entry became, and the real public source behind it.

Each entry: (sec, n) -> dict with
  id, title, publisher, summary, source(name, home, license), handler, cfg, params,
  key (env var for a free key, optional), swap (why the PDF dataset was replaced, if it was).
`handler` names a connector in api/_lib/connectors.js. `cfg` is passed to it as-is.
Params: (name, required, description, default).
"""

PD = "Public domain (US government work)"
CC0 = "CC0 1.0"
CCBY4 = "CC BY 4.0"
CCBYSA = "CC BY-SA 4.0"
ODBL = "ODbL 1.0 (OpenStreetMap contributors)"
WIKI = "CC0 (Wikimedia pageview data)"

LATLON = [("lat", True, "Latitude", "39.9612"), ("lon", True, "Longitude", "-82.9988"), ("radius", False, "Radius in metres (max 5000)", "1500")]
ZIP = [("zip", True, "5-digit US ZIP code", "43215")]
Q = lambda d, default: [("q", True, d, default)]

